def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # dp[i1][i2] = maximum sum when first path is at (i1, j1) and second at (i2, j2)
    # where j1 = k - i1, j2 = k - i2 for current step k
    NEG_INF = -10**15
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]  # start at (1,1)

    for k in range(2, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # consider all combinations of previous moves
                for di1 in (0, 1):  # 0: came from left (i1 same), 1: came from up (i1-1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        pj1 = (k - 1) - pi1
                        pj2 = (k - 1) - pi2
                        if pj1 < 1 or pj1 > N or pj2 < 1 or pj2 > N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val == NEG_INF:
                            continue
                        best = max(best, prev_val)
                if best == NEG_INF:
                    continue
                cell_val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell_val += grid[i2][j2]
                dp_cur[i1][i2] = best + cell_val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

