def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m > sum(a):
        return 0
    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1
    for i in range(n):
        limit = a[i]
        dp_cur = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp_prev[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                dp_cur[j] = prefix[j]
            else:
                dp_cur[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp_prev = dp_cur
    return dp_prev[m] % MOD

