def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find the maximum bitonic subsequence length
    max_len = 0
    for i in range(n):
        cur_len = lis[i] + lds[i] - 1
        if cur_len > max_len:
            max_len = cur_len

    # Minimum removals = total students - longest bitonic subsequence
    return n - max_len
